UPDATE SYT0MC
   SET BFIL_AEK     = COALESCE(#{bfilAek, jdbcType=NUMERIC}, 0)
     , UP_AEK       = COALESCE(#{upAek, jdbcType=NUMERIC}, 0)
     , DW_AEK       = COALESCE(#{dwAek, jdbcType=NUMERIC}, 0)
     , WON_BFIL_AEK = COALESCE(#{wonBfilAek, jdbcType=NUMERIC}, 0)
     , WON_UP_AEK   = COALESCE(#{wonUpAek, jdbcType=NUMERIC}, 0)
     , WON_DW_AEK   = COALESCE(#{wonDwAek, jdbcType=NUMERIC}, 0)
 WHERE CORP_GR  = #{corpGr, jdbcType=VARCHAR}
   AND TR_YMD   = TO_DATE(REPLACE(#{trYmd, jdbcType=VARCHAR}, '-', ''), 'YYYYMMDD')
   AND TR_CD    = #{trCd, jdbcType=VARCHAR}
   AND FUND_CD  = #{fundCd, jdbcType=VARCHAR}
   AND TRUSTEE  = #{trustee, jdbcType=VARCHAR}
   AND CURRENCY = #{currency, jdbcType=VARCHAR}

